def generate_orientation_texture(width=8, height=8):
    """影像上半紅、下半藍；用非對稱顏色檢查 UV 的 v 向上。"""
    tex = np.zeros((height, width, 3), dtype=np.float32)
    for y in range(height):
        tex[y, :, :] = ([1.0, 0.0, 0.0] if y < height // 2
                        else [0.0, 0.0, 1.0])
    return tex

